    },
    "origin": {
      "$ref": "montagent://schema/def/Origin.json"
    },
    "width": {
      "type": "integer",
      "format": "int64",
      "description": "The box the text must fit inside — required, because an omitted `height` would be\nindistinguishable from a decision not to check (ADR-0014). It is a *container\nclaim*, not drawn geometry, which is why a stroke grows into it rather than past it."
    },
    "height": {
      "type": "integer",
      "format": "int64"
    },
    "font": {
      "type": "string",
      "description": "A key into the project's `fonts` table, never a system family name."
    },
    "size": {
      "type": "integer",
      "format": "int64",
      "description": "A literal number. The renderer never chooses a size and never chooses a line break\n(ADR-0007) — the fitted sizes in the fixture came from a pipeline that measured and\nwrote literals, and that loop moves to authoring time rather than disappearing.\n\nAn integer, by ADR-0012's absolute-integer-pixels rule: a size is a length in the\nproject's frame space, like `width` and `height`, and all 22 of the fixture's text\nelements carry one. A float would additionally give every whole size two spellings —\n`55` and `55.0` — which is the ambiguity `center-center` and the `scale` union were\neach retired for."
    },
    "line_height": {
      "type": "number",
      "format": "double",
      "description": "Restricted to one decimal digit, always exactly representable as `n/10`, so the\nblock-height derivation is exact integer arithmetic and never IEEE double\n(ADR-0028). Defaults to `1.2` when omitted."
    },
    "color": {
      "$ref": "montagent://schema/def/Colour.json"
    },
    "align": {
      "$ref": "montagent://schema/def/Align.json"
    },
    "runs": {
      "type": "array",
      "items": {
        "$ref": "montagent://schema/def/Run.json"
      }
    },
    "stroke": {
      "$ref": "montagent://schema/def/Colour.json"
    },
    "stroke_width": {
      "type": "integer",
      "format": "int64"
    },
    "scale": {
      "$ref": "montagent://schema/def/AnimatableArray_size_2_of_double.json"
    },
    "rotation": {
      "$ref": "montagent://schema/def/Animatabledouble.json"
    },
    "opacity": {
      "$ref": "montagent://schema/def/Animatabledouble.json"
    },
    "effects": {
      "type": "array",
      "items": {
        "$ref": "montagent://schema/index.json#/effects"
      }
    },
    "caption": {
      "type": "boolean",
      "description": "`false` says this text is not a caption — a title, a lower-third, a logo, a\nkinetic word — and silences all four caption checks on it: `R-CAPTION-PACE`,\n`R-CAPTION-MIN-DURATION`, `R-CAPTION-NO-AUDIO` and `R-CAPTION-REPEAT-DURATION`, whose\ngrouping of identical text leaves it out. Omitted means `true`: every text element\nis a caption unless it says otherwise. It changes no pixel and no other check\n(ADR-0136)."
    }
  },
  "required": [
    "id",
    "type",
    "start",
    "end",
    "width",
    "height",
    "font",
    "size",
    "runs"
  ],
  "description": "`x, y, origin, width, height, font, size, line_height, color, align, runs` — ADR-0041's\nmeasured order — then the paint ADR-0014 adds, the transform properties, `effects`, and\nlast `caption`, which draws nothing and so follows everything that does (ADR-0136)."
}
"}]}

